model.view:
{
  "version": 1,
  "state": [
    {
      "id": "stopped",
      "when": {
        "eq": [
          {
            "var": "up"
          },
          "FALSE"
        ]
      },
      "label": "Stopped; durable pieces and saved record remain"
    },
    {
      "id": "running",
      "when": true,
      "label": "Track one recording and its pieces"
    }
  ],
  "step": [
    {
      "id": "BeginPiece",
      "when": {
        "eq": [
          {
            "action": true
          },
          "BeginPiece"
        ]
      },
      "label": "Save a request to write the next hidden piece"
    },
    {
      "id": "WriteHidden",
      "when": {
        "eq": [
          {
            "action": true
          },
          "WriteHidden"
        ]
      },
      "label": "Caller writes hidden bytes"
    },
    {
      "id": "FlushHidden",
      "when": {
        "eq": [
          {
            "action": true
          },
          "FlushHidden"
        ]
      },
      "label": "Caller makes the piece bytes durable"
    },
    {
      "id": "ReportFlushed",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ReportFlushed"
        ]
      },
      "label": "Save permission to name the durable piece"
    },
    {
      "id": "NamePiece",
      "when": {
        "eq": [
          {
            "action": true
          },
          "NamePiece"
        ]
      },
      "label": "Caller gives the whole piece its name"
    },
    {
      "id": "ReportNamed",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ReportNamed"
        ]
      },
      "label": "Record the named piece as closed"
    },
    {
      "id": "ReportWriteFailure",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ReportWriteFailure"
        ]
      },
      "label": "Keep closed pieces and report that capture cannot continue"
    },
    {
      "id": "CaptureEnds",
      "when": {
        "eq": [
          {
            "action": true
          },
          "CaptureEnds"
        ]
      },
      "label": "Capture ends; another part chooses whether to carry on"
    },
    {
      "id": "EndForGood",
      "when": {
        "eq": [
          {
            "action": true
          },
          "EndForGood"
        ]
      },
      "label": "The caller says to finish this recording"
    },
    {
      "id": "CarryOn",
      "when": {
        "eq": [
          {
            "action": true
          },
          "CarryOn"
        ]
      },
      "label": "Another part chooses to carry on after the last closed piece"
    },
    {
      "id": "DiscardHidden",
      "when": {
        "eq": [
          {
            "action": true
          },
          "DiscardHidden"
        ]
      },
      "label": "Caller discards an unfinished hidden piece"
    },
    {
      "id": "ReportHiddenDiscarded",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ReportHiddenDiscarded"
        ]
      },
      "label": "Acknowledge cleanup before reusing the open number"
    },
    {
      "id": "FinishEmpty",
      "when": {
        "eq": [
          {
            "action": true
          },
          "FinishEmpty"
        ]
      },
      "label": "Report that nothing was recorded"
    },
    {
      "id": "RequestJoin",
      "when": {
        "eq": [
          {
            "action": true
          },
          "RequestJoin"
        ]
      },
      "label": "Save a join request containing every closed piece in order"
    },
    {
      "id": "WriteJoinPartial",
      "when": {
        "eq": [
          {
            "action": true
          },
          "WriteJoinPartial"
        ]
      },
      "label": "Caller writes a partial joined file"
    },
    {
      "id": "SaveJoinGaps",
      "when": {
        "eq": [
          {
            "action": true
          },
          "SaveJoinGaps"
        ]
      },
      "label": "Save omitted pieces and their durations before naming the join"
    },
    {
      "id": "NameJoinedFile",
      "when": {
        "eq": [
          {
            "action": true
          },
          "NameJoinedFile"
        ]
      },
      "label": "Caller names the whole joined file"
    },
    {
      "id": "ReportJoinNamed",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ReportJoinNamed"
        ]
      },
      "label": "Record successful joining"
    },
    {
      "id": "ReportJoinFailure",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ReportJoinFailure"
        ]
      },
      "label": "Keep the recording and report the join error and spool location"
    },
    {
      "id": "PersonRetriesJoin",
      "when": {
        "eq": [
          {
            "action": true
          },
          "PersonRetriesJoin"
        ]
      },
      "label": "A person requests another join attempt"
    },
    {
      "id": "DiscardJoinPartial",
      "when": {
        "eq": [
          {
            "action": true
          },
          "DiscardJoinPartial"
        ]
      },
      "label": "Caller discards the unfinished joined file"
    },
    {
      "id": "ReportJoinDiscarded",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ReportJoinDiscarded"
        ]
      },
      "label": "Prepare to retry with every closed piece"
    },
    {
      "id": "RequestHandover",
      "when": {
        "eq": [
          {
            "action": true
          },
          "RequestHandover"
        ]
      },
      "label": "Request the same joined file with the stable recording identity"
    },
    {
      "id": "CopyAndVerifyHandover",
      "when": {
        "eq": [
          {
            "action": true
          },
          "CopyAndVerifyHandover"
        ]
      },
      "label": "The hand-over part copies and verifies the single archive file"
    },
    {
      "id": "ReportHandoverSuccess",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ReportHandoverSuccess"
        ]
      },
      "label": "Save confirmed hand-over; keep the pieces for three days"
    },
    {
      "id": "ReportHandoverFailure",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ReportHandoverFailure"
        ]
      },
      "label": "Keep every piece and report the hand-over error"
    },
    {
      "id": "PersonRetriesHandover",
      "when": {
        "eq": [
          {
            "action": true
          },
          "PersonRetriesHandover"
        ]
      },
      "label": "A person requests the same hand-over again"
    },
    {
      "id": "RetentionElapsed",
      "when": {
        "eq": [
          {
            "action": true
          },
          "RetentionElapsed"
        ]
      },
      "label": "Caller reports that three days after hand-over have passed"
    },
    {
      "id": "RequestRemoval",
      "when": {
        "eq": [
          {
            "action": true
          },
          "RequestRemoval"
        ]
      },
      "label": "Save permission to remove the retained pieces"
    },
    {
      "id": "RemovePiece",
      "when": {
        "eq": [
          {
            "action": true
          },
          "RemovePiece"
        ]
      },
      "label": "Caller removes a retained piece"
    },
    {
      "id": "ReportRemovalFinished",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ReportRemovalFinished"
        ]
      },
      "label": "Record completed piece cleanup"
    },
    {
      "id": "Crash",
      "when": {
        "eq": [
          {
            "action": true
          },
          "Crash"
        ]
      },
      "label": "On Air dies; only durable state survives"
    },
    {
      "id": "Recover",
      "when": {
        "eq": [
          {
            "action": true
          },
          "Recover"
        ]
      },
      "label": "Reconcile the disk listing and saved record at the next launch"
    },
    {
      "id": "Wait",
      "when": {
        "eq": [
          {
            "action": true
          },
          "Wait"
        ]
      },
      "label": "Wait for an outside event or remain finished"
    },
    {
      "id": "other",
      "when": true,
      "label": "Advance recording bookkeeping"
    }
  ]
}

